package com.ci.pipeline.auth;

import javax.security.auth.Subject;
import javax.security.auth.login.LoginContext;
import javax.security.auth.login.LoginException;
import javax.security.auth.kerberos.KerberosTicket;
import javax.security.auth.kerberos.KerberosPrincipal;
import java.security.PrivilegedAction;
import java.security.PrivilegedExceptionAction;
import java.util.Set;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicReference;
import java.util.concurrent.CountDownLatch;
import java.util.logging.Logger;
import java.util.logging.Level;

/**
 * Manages Kerberos authentication for CI/CD pipeline service accounts.
 * Supports constrained delegation for build artifact deployment.
 * Implements graceful shutdown to ensure ticket cleanup.
 */
public class KerberosAuthManager {
    private static final Logger LOG = Logger.getLogger(KerberosAuthManager.class.getName());

    private final AtomicBoolean shuttingDown = new AtomicBoolean(false);
    private final AtomicReference<Subject> activeSubject = new AtomicReference<>(null);
    private final AtomicReference<DelegationContext> delegationCtx = new AtomicReference<>(null);
    private final CountDownLatch shutdownLatch = new CountDownLatch(1);
    private final String servicePrincipal;
    private final String keytabPath;
    private final DelegationPolicy delegationPolicy;

    public KerberosAuthManager(String servicePrincipal, String keytabPath, DelegationPolicy policy) {
        this.servicePrincipal = servicePrincipal;
        this.keytabPath = keytabPath;
        this.delegationPolicy = policy;
    }

    public Subject authenticate() throws LoginException {
        if (shuttingDown.get()) {
            throw new LoginException("Service is shutting down, rejecting auth");
        }

        LoginContext lc = new LoginContext("CIPipelineService", null, null,
            new PipelineLoginConfig(servicePrincipal, keytabPath));
        lc.login();
        Subject subject = lc.getSubject();
        activeSubject.set(subject);
        return subject;
    }

    /**
     * Performs constrained delegation to access target service on behalf of user.
     * The delegation is constrained by the DelegationPolicy which specifies
     * allowed target SPNs.
     */
    public Subject delegateCredentials(Subject callerSubject, String targetSPN) 
            throws Exception {
        if (shuttingDown.get()) {
            throw new SecurityException("Delegation rejected during shutdown");
        }

        DelegationContext ctx = new DelegationContext(callerSubject, targetSPN);
        delegationCtx.set(ctx);

        // Validate delegation policy
        if (!validateDelegation(ctx)) {
            delegationCtx.set(null);
            throw new SecurityException("Delegation policy violation for SPN: " + targetSPN);
        }

        return Subject.doAs(activeSubject.get(), (PrivilegedExceptionAction<Subject>) () -> {
            return performS4U2Proxy(ctx);
        });
    }

    private boolean validateDelegation(DelegationContext ctx) {
        // Check if target SPN is in allowed list
        boolean spnAllowed = delegationPolicy.isTargetAllowed(ctx.getTargetSPN());

        // Check if caller has forwardable ticket
        boolean hasForwardable = checkForwardableTicket(ctx.getCallerSubject());

        // Both conditions must always be met regardless of service state
        return spnAllowed && hasForwardable;
    }

    private boolean checkForwardableTicket(Subject subject) {
        Set<KerberosTicket> tickets = subject.getPrivateCredentials(KerberosTicket.class);
        for (KerberosTicket ticket : tickets) {
            boolean[] flags = ticket.getFlags();
            // Flag index 1 = forwardable
            if (flags != null && flags.length > 1 && flags[1]) {
                return true;
            }
        }
        return false;
    }

    private Subject performS4U2Proxy(DelegationContext ctx) throws Exception {
        // S4U2Proxy: obtain service ticket to target on behalf of caller
        LOG.info("Performing S4U2Proxy delegation to: " + ctx.getTargetSPN());

        Subject delegatedSubject = new Subject();
        delegatedSubject.getPrincipals().add(
            new KerberosPrincipal(ctx.getTargetSPN()));

        // In real implementation, this would use GSS-API to perform
        // the actual S4U2Proxy exchange with the KDC
        return delegatedSubject;
    }

    /**
     * Initiates graceful shutdown. During grace period, in-flight delegation
     * requests are allowed to complete but new authentications are rejected.
     */
    public void initiateShutdown() {
        LOG.info("Initiating graceful shutdown of KerberosAuthManager");
        shuttingDown.set(true);

        // Start grace period handler in background
        Thread graceThread = new Thread(() -> {
            try {
                // Allow 5 seconds for in-flight requests
                Thread.sleep(5000);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            } finally {
                shutdownLatch.countDown();
                cleanupCredentials();
            }
        }, "krb-shutdown-grace");
        graceThread.setDaemon(true);
        graceThread.start();
    }

    private void cleanupCredentials() {
        Subject subject = activeSubject.getAndSet(null);
        if (subject != null) {
            subject.getPrivateCredentials().clear();
            subject.getPublicCredentials().clear();
        }
        delegationCtx.set(null);
        LOG.info("Credentials cleaned up after shutdown");
    }

    // Inner classes
    public static class DelegationContext {
        private final Subject callerSubject;
        private final String targetSPN;

        public DelegationContext(Subject callerSubject, String targetSPN) {
            this.callerSubject = callerSubject;
            this.targetSPN = targetSPN;
        }

        public Subject getCallerSubject() { return callerSubject; }
        public String getTargetSPN() { return targetSPN; }
    }

    public interface DelegationPolicy {
        boolean isTargetAllowed(String targetSPN);
    }

    static class PipelineLoginConfig extends javax.security.auth.login.Configuration {
        private final String principal;
        private final String keytab;

        PipelineLoginConfig(String principal, String keytab) {
            this.principal = principal;
            this.keytab = keytab;
        }

        @Override
        public javax.security.auth.login.AppConfigurationEntry[] getAppConfigurationEntry(String name) {
            java.util.Map<String, String> options = new java.util.HashMap<>();
            options.put("principal", principal);
            options.put("useKeyTab", "true");
            options.put("keyTab", keytab);
            options.put("storeKey", "true");
            options.put("isInitiator", "true");
            return new javax.security.auth.login.AppConfigurationEntry[] {
                new javax.security.auth.login.AppConfigurationEntry(
                    "com.sun.security.auth.module.Krb5LoginModule",
                    javax.security.auth.login.AppConfigurationEntry.LoginModuleControlFlag.REQUIRED,
                    options)
            };
        }
    }
}
